class Account:
    def __init__(self, balance):
        self.balance = balance
    def deposit(self, n):
        self.balance += n
    def withdraw(self, n):
        if n > self.balance:
            print("잔액 부족")
        else:
            self.balance -= n
a = Account(int(input()))
a.deposit(int(input()))
a.withdraw(int(input()))
print(f"잔액: {a.balance}원")

