class Pet:
    def __init__(self, name):
        self.name = name
    def info(self):
        print("이름:", self.name)
class Dog(Pet):
    def __init__(self, name, trick):
        super().__init__(name)
        self.trick = trick
    def show(self):
        self.info()
        print("재주:", self.trick)
name = input()
trick = input()
d = Dog(name, trick)
d.show()

